func (h notifierHost) Permissions(ctx context.Context, user string) ([]string, error) {
	id, err := ParseUserID(user)
	if err != nil {
		return nil, nil
	}
	ctx = AsSystem(ctx)
	repositories := h.repositories()
	grants, _, err := repositories.GetUserRoleGrantRepository().FindMany(ctx, &UserRoleGrantFilter{UserID: &UUIDFilter{Eq: &id}}, &UserRoleGrantFindOptions{Fields: UserRoleGrantFields{}.All(), Limit: 1000, SkipCount: true})
	if err != nil {
		return nil, err
	}
	// The grants' roles, in one read.
	var roleIDs []types.IdentityUUID
	for _, grant := range grants {
		if grant.Role.Id != nil {
			roleIDs = append(roleIDs, *grant.Role.Id)
		}
	}
	if len(roleIDs) == 0 {
		return []string{}, nil
	}
	roles, _, err := repositories.GetRoleRepository().FindMany(ctx, &RoleFilter{Id: &UUIDFilter{In: roleIDs}}, &RoleFindOptions{Fields: RoleFields{}.All(), Limit: len(roleIDs), SkipCount: true})
	if err != nil {
		return nil, err
	}
	byID := make(map[types.IdentityUUID]*types.Role, len(roles))
	for _, role := range roles {
		if role.Id != nil {
			byID[*role.Id] = role
		}
	}
	seen := map[string]bool{}
	out := []string{}
	for _, grant := range grants {
		if grant.Role.Id == nil {
			continue
		}
		role, found := byID[*grant.Role.Id]
		if !found {
			continue
		}
		for _, permission := range role.Permissions {
			if !seen[permission] {
				seen[permission] = true
				out = append(out, permission)
			}
		}
	}
	return out, nil
}

func (h notifierHost) RoleHolders(ctx context.Context, role string) ([]string, error) {
	ctx = AsSystem(ctx)
	repositories := h.repositories()
	found, err := repositories.GetRoleRepository().FindOne(ctx, &RoleFilter{Name: &StringFilter{Eq: &role}}, nil)
	if errors.Is(err, ErrNotFound) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	grants, _, err := repositories.GetUserRoleGrantRepository().FindMany(ctx, &UserRoleGrantFilter{RoleID: &UUIDFilter{Eq: found.Id}}, &UserRoleGrantFindOptions{Fields: UserRoleGrantFields{}.All(), Limit: 10000, SkipCount: true})
	if err != nil {
		return nil, err
	}
	var out []string
	for _, grant := range grants {
		if grant.User.Id != nil {
			out = append(out, grant.User.Id.String())
		}
	}
	return out, nil
}

